style:
/* 夜航 —— 藏青侧栏通到页顶，右上角 RESUME 水印 */

.tw-yehang.layout-sidebar.resume-paper {
  padding-top: 0;
}

.tw-yehang.layout-sidebar.resume-paper .paper-header {
  position: relative;
  margin: 0 -15mm;
  padding: 11mm 15mm 6mm;
  background: #16324f;
  border: none;
  color: #fff;
  align-items: flex-start;
  gap: 7mm;
  print-color-adjust: exact;
}

.tw-yehang.layout-sidebar.resume-paper .paper-header::after {
  content: "RESUME";
  position: absolute;
  top: 9mm;
  right: 14mm;
  color: rgba(255, 255, 255, 0.16);
  font-size: calc(var(--paper-base-size) * 3.4);
  font-weight: 700;
  letter-spacing: 0.12em;
  line-height: 1;
  print-color-adjust: exact;
}

.tw-yehang.layout-sidebar.resume-paper .paper-photo {
  order: -1;
  width: 26mm;
  height: 34mm;
  border: 0.5mm solid rgba(255, 255, 255, 0.45);
  border-radius: 0;
  box-shadow: none;
}

.tw-yehang.layout-sidebar.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.12);
  color: #fff;
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 700;
}

.tw-yehang.layout-sidebar.resume-paper .paper-name {
  color: #fff;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.05);
  letter-spacing: 0.1em;
}

.tw-yehang.layout-sidebar.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: rgba(255, 255, 255, 0.64);
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-yehang.layout-sidebar.resume-paper .paper-role {
  margin-top: 1.6mm;
  color: rgba(255, 255, 255, 0.84);
  font-size: calc(var(--paper-base-size) * 0.9);
  font-weight: 400;
  line-height: 1.7;
}

.tw-yehang.layout-sidebar.resume-paper .paper-contacts {
  display: flex;
  flex-wrap: wrap;
  gap: 1.4mm 6mm;
  margin-top: 3mm;
  color: rgba(255, 255, 255, 0.86);
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-yehang.layout-sidebar.resume-paper .paper-contact__label {
  color: rgba(255, 255, 255, 0.52);
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-layout {
  align-items: stretch;
  grid-template-columns: 62mm minmax(0, 1fr);
  column-gap: 0;
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-aside {
  grid-column: 1;
  margin: 0 0 0 -15mm;
  padding: 2mm 6mm 6mm 15mm;
  background: #16324f;
  border-top: none;
  color: rgba(255, 255, 255, 0.9);
  print-color-adjust: exact;
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-main {
  grid-column: 2;
  padding-left: 8mm;
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-aside .paper-section__title {
  display: block;
  margin-bottom: 2.6mm;
  padding: 0 0 1.2mm;
  border: none;
  border-bottom: 0.25mm solid rgba(255, 255, 255, 0.3);
  color: #fff;
  font-size: calc(var(--paper-base-size) * 0.96);
  letter-spacing: 0.12em;
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-aside .paper-section__icon {
  display: none;
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-aside .paper-section__body,
.tw-yehang.layout-sidebar.resume-paper .sidebar-aside .paper-item-title,
.tw-yehang.layout-sidebar.resume-paper .sidebar-aside .paper-item-sub,
.tw-yehang.layout-sidebar.resume-paper .sidebar-aside .paper-item-period,
.tw-yehang.layout-sidebar.resume-paper .sidebar-aside .paper-rich,
.tw-yehang.layout-sidebar.resume-paper .sidebar-aside .paper-note,
.tw-yehang.layout-sidebar.resume-paper .sidebar-aside .paper-plain {
  color: rgba(255, 255, 255, 0.86);
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-aside .paper-rich li::marker {
  color: rgba(255, 255, 255, 0.55);
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-main .paper-section__title {
  display: block;
  margin-bottom: 2.8mm;
  padding-bottom: 1.4mm;
  border-bottom: 0.3mm solid #16324f;
  color: #16324f;
  font-size: calc(var(--paper-base-size) * 1.1);
  letter-spacing: 0.1em;
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-main .paper-section__icon {
  display: none;
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-main .paper-section__body {
  color: #33393d;
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-main .paper-item-title {
  color: #1c252b;
  font-size: calc(var(--paper-base-size) * 1.02);
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-main .paper-item-period {
  color: #78878f;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-main .paper-item-sub {
  color: #46545c;
}

.tw-yehang.layout-sidebar.resume-paper .paper-rich ul,
.tw-yehang.layout-sidebar.resume-paper .paper-rich ol {
  padding-left: 1.1em;
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-main .paper-rich li::marker {
  color: #8e9aa2;
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-aside .paper-skills {
  grid-template-columns: minmax(0, 1fr);
  gap: 1.8mm;
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-aside .paper-skill {
  padding-bottom: 0.8mm;
  border-bottom: 0.2mm solid rgba(255, 255, 255, 0.16);
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-aside .paper-skill__name {
  display: flex;
  flex: 1;
  align-items: baseline;
  gap: 2mm;
  color: rgba(255, 255, 255, 0.88);
  font-size: calc(var(--paper-base-size) * 0.86);
  font-weight: 400;
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-aside .paper-skill__name::after {
  content: "";
  flex: 1;
  border-bottom: 0.2mm dotted rgba(255, 255, 255, 0.3);
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-aside .paper-skill__dots {
  display: none;
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-aside .paper-skill__level {
  display: inline;
  color: rgba(255, 255, 255, 0.62);
  font-size: calc(var(--paper-base-size) * 0.78);
}

.tw-yehang.layout-sidebar.resume-paper .sidebar-aside .paper-note__tag {
  color: #fff;
  font-weight: 600;
}

.tw-yehang.layout-sidebar.resume-paper .paper-footer {
  border-top: 0.2mm solid #e3e8ec;
  color: #9aa6ae;
}
